style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
/* -----------------------------------
   OLED PALETTE (Improved Text)
   ----------------------------------- */
:root {
  --bg: #000000;
  --bg-alt: #0a0a0a;

  /* Brighter, more readable text */
  --text: hsl(220, 40%, 92%);
  --text-muted: hsl(220, 25%, 75%);

  --border: hsl(230, 16%, 20%);
  --button: hsl(230, 20%, 20%);
  --link: hsl(215, 60%, 60%);
  --link-visited: hsl(326, 60%, 60%);
  --selection: hsl(210, 60%, 40%);
}

/* -----------------------------------
   NEUTRALISE SITE VARIABLES
   ----------------------------------- */
:root, * {
    --background: var(--bg) !important;
    --background-color: var(--bg) !important;
    --surface: var(--bg-alt) !important;
    --card: var(--bg-alt) !important;
    --panel: var(--bg-alt) !important;
    --color-bg: var(--bg) !important;
    --color-surface: var(--bg-alt) !important;
    --color-base: var(--bg) !important;

    /* Fix sites that use text variables */
    --text-color: var(--text) !important;
    --text-primary: var(--text) !important;
    --text-secondary: var(--text-muted) !important;
    --color-text: var(--text) !important;
    --color-text-primary: var(--text) !important;
    --color-text-secondary: var(--text-muted) !important;
}

/* -----------------------------------
   NUCLEAR DARK MODE (ML-style)
   ----------------------------------- */
*:not(img):not(video):not(canvas):not(svg):not([style*="background-image"]) {
    background-color: var(--bg) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
}

/* -----------------------------------
   RESTORE LAYERED CONTAINERS
   ----------------------------------- */
div, section, article, header, footer, nav, main, aside {
    background-color: var(--bg-alt) !important;
    color: var(--text) !important;
}

/* -----------------------------------
   TEXT FIXES (Brightness + Opacity)
   ----------------------------------- */
*, *::before, *::after {
    opacity: 1 !important; /* Fix dimmed text */
    color: var(--text) !important;
}

small, .muted, .subtle {
    color: var(--text-muted) !important;
}

/* -----------------------------------
   LINKS
   ----------------------------------- */
a {
    color: var(--link) !important;
}

a:visited {
    color: var(--link-visited) !important;
}

/* -----------------------------------
   BUTTONS
   ----------------------------------- */
button,
input[type="button"],
input[type="submit"],
input[type="reset"] {
    background: var(--button) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
}

/* -----------------------------------
   FORMS
   ----------------------------------- */
input, textarea, select {
    background-color: var(--bg-alt) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
}

/* -----------------------------------
   TABLES
   ----------------------------------- */
table, tr, td, th {
    background-color: var(--bg-alt) !important;
    color: var(--text) !important;
    border-color: var(--border) !important;
}

/* -----------------------------------
   KILL GRADIENTS (ML behaviour)
   ----------------------------------- */
* {
    background-image: none !important;
}

/* -----------------------------------
   SELECTION
   ----------------------------------- */
::selection {
    background: var(--selection) !important;
    color: #fff !important;
}
}
